// Transcribed from solid-js@2.0.0-rc.9, the prerelease this repository audits.
//
// `solid-js` re-exports these from `@solidjs/signals`. Every declaration below
// is byte-faithful to `@solidjs/signals@2.0.0-rc.9`, JSDoc dropped:
//
// - `Disposable`                                  `dist/types/core/types.d.ts:4-6`
// - `onCleanup`                                   `dist/types/signals.d.ts:41`
// - `ComputeFunction`, `EffectFunction`,
//   `EffectBundle`, `BaseEffectOptions`,
//   `EffectOptions`                               `dist/types/signals.d.ts:68-136`
// - `NoInfer`                                     `dist/types/signals.d.ts:225`
// - `createEffect`                                `dist/types/signals.d.ts:367`
// - `createRenderEffect`                          `dist/types/signals.d.ts:397`
//
// Added for ADR 0183's `owned-computation-callbacks`, from the same release:
//
// - `$REFRESH`, `Refreshable`                      `dist/types/core/constants.d.ts:204,213-215`
// - `Accessor`, `SourceAccessor`                  `dist/types/signals.d.ts:49-50`
// - `MemoOptions`                                 `dist/types/signals.d.ts:158-224`
// - `createMemo`                                  `dist/types/signals.d.ts:295-298`
// - `createRoot`                                  `dist/types/core/owner.d.ts:121-124`
// - `onSettled`                                   `dist/types/signals.d.ts:738`
//
// Nothing on the argument side is reduced.

export interface Disposable {
    (): void;
}
export declare function onCleanup(fn: Disposable): Disposable;
export type ComputeFunction<Prev, Next extends Prev = Prev> = (v: Prev) => PromiseLike<Next> | AsyncIterable<Next> | Next;
export type EffectFunction<Prev, Next extends Prev = Prev> = (v: Next, p?: Prev) => (() => void) | void;
export type EffectBundle<Prev, Next extends Prev = Prev> = {
    effect: EffectFunction<Prev, Next>;
    error: (err: unknown, cleanup: () => void) => void;
};
interface BaseEffectOptions {
    name?: string;
}
export interface EffectOptions extends BaseEffectOptions {
    defer?: boolean;
    schedule?: boolean;
    sync?: boolean;
    transparent?: boolean;
}
export type NoInfer<T extends any> = [T][T extends any ? 0 : never];
export declare function createEffect<T>(compute: ComputeFunction<undefined | NoInfer<T>, T>, effectFn: EffectFunction<NoInfer<T>, T> | EffectBundle<NoInfer<T>, T>, options?: EffectOptions): void;
export declare function createRenderEffect<T>(compute: ComputeFunction<undefined | NoInfer<T>, T>, effectFn: EffectFunction<NoInfer<T>, T>, options?: EffectOptions): void;

export declare const $REFRESH: unique symbol;
export type Refreshable<T> = T & {
    readonly [$REFRESH]: any;
};
export type Accessor<T> = () => T;
export type SourceAccessor<T> = Refreshable<Accessor<T>>;
export interface MemoOptions<T> {
    id?: string;
    name?: string;
    transparent?: boolean;
    equals?: false | ((prev: T, next: T) => boolean);
    unobserved?: () => void;
    lazy?: boolean;
    sync?: boolean;
    loadingValue?: T;
}
export declare function createMemo<T>(compute: ComputeFunction<NoInfer<T>, T>, options: MemoOptions<T> & {
    loadingValue: T;
}): SourceAccessor<T>;
export declare function createMemo<T>(compute: ComputeFunction<undefined | NoInfer<T>, T>, options?: MemoOptions<T>): SourceAccessor<T>;
export declare function createRoot<T>(init: ((dispose: () => void) => T) | (() => T), options?: {
    id?: string;
    transparent?: boolean;
}): T;
export declare function onSettled(callback: () => void | (() => void)): void;
